import{z as A,x as n,o as t,c as p,q as l,j as o,D as e,d as r,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"掩模成本与周期","description":"","frontmatter":{"title":"掩模成本与周期","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-cost-cycle.md","filePath":"litho/mask-cost-cycle.md","lastUpdated":1791413859000}'),d={name:"litho/mask-cost-cycle.md"};function h(B,a,c,m,_,T){const E=n("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="掩模成本与周期" tabindex="-1">掩模成本与周期 <a class="header-anchor" href="#掩模成本与周期" aria-label="Permalink to &quot;掩模成本与周期&quot;">​</a></h1><div class="epigraph"><p>先进层的钱与日子花在写、检验、光化鉴定和返工上；多重图形把张数乘上去，EUV 把单张难度乘上去。</p><footer>—— 对照掩模成本结构与 TAPOUT 周期的公开产业讨论；不编造某层美元报价</footer></div><p><a href="/litho/mask-haze">上一课</a>把寿命与再清洗钉进物流。缺口是把本门课收成账：一张版多少钱、多少天，以及高 NA 晶圆经济如何被「等版」卡住。本课钉掩模成本与周期。仿真课从<a href="/litho/fdtd-mask">下一课</a>另起，用严格电磁去解释为何有些版必须那么难写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/high-na-throughput-economics">高 NA 产能经济</a> 算的是扫描机小时。掩模是另一条关键路径：空白片交期、MDP、写入、检验、修复、AIMS、 pellicle、运输、改版迭代。关键层单张周期以周计并不罕见；多重图形一层多张，改设计规则等于改一组版。EUV 减少张数，但单张写入与光化检验更贵。</p><p>缺口是<strong>张数 × 单张难度 × 迭代次数</strong>，不是给某厂报价单。把「EUV 省掩模」写成免费，会漏掉单张成本与光化工具产能。</p><h3 id="不要引用无来源的美元" tabindex="-1">不要引用无来源的美元 <a class="header-anchor" href="#不要引用无来源的美元" aria-label="Permalink to &quot;不要引用无来源的美元&quot;">​</a></h3><p>公开叙事可以谈结构（写模机折旧、空白片、人工、光化 AIMS 稀缺、ILT 数据），不可以把传闻「一张 EUV 版 xx 万美元」写成事实。本课只钉成本驱动项。</p><p><span class="marginnote">改一次 OPC 若强制重写全套分解版，周期按最慢那张走。DTCO 冻结规则的价值，有一截是少改版。</span></p><p><span class="marginnote">常见误区：初学者容易以为改版成本就是「重写那一张」。实际上改一次关键层的 OPC 常触发整套分解版一起重做，张数与周期一起翻倍，产品上市日历按最慢的那张往后推——这就是设计冻结值钱的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本分解：坯 + 膜、写入机时（家族公式见 <a href="/litho/mask-write-time">写入时间</a>）、检验与 AIMS 机时、修复、 pellicle、合格率（报废摊到好版上）、物流。周期分解：排队 + 工艺 + 等待 AIMS/光化空白检验。产能规划按瓶颈机台（多束、光化检验）而不是按平均层。</p>',12)),(t(),o(i,null,{default:e(()=>[s(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E7%A9%BA%E7%99%BD%E5%9D%AF%E5%88%B0%E8%B4%A7%20%E6%8E%92%E9%98%9F%22%5D%20--%3E%20W%5B%22MDP%20%E4%B8%8E%E5%86%99%E5%85%A5%E6%9C%BA%E6%97%B6%22%5D%0A%20%20W%20--%3E%20I%5B%22%E7%BC%BA%E9%99%B7%E6%A3%80%E9%AA%8C%22%5D%0A%20%20I%20--%3E%20F%5B%22%E7%BC%BA%E9%99%B7%E4%BF%AE%E5%A4%8D%E4%B8%8E%E9%87%8D%E6%A3%80%22%5D%0A%20%20F%20--%3E%20A%5B%22AIMS%20%2F%20%E5%85%89%E5%8C%96%E9%89%B4%E5%AE%9A%22%5D%0A%20%20A%20--%3E%20P%5B%22%E8%A3%85%20pellicle%20%E4%B8%8E%E8%BF%90%E8%BE%93%22%5D%0A%20%20P%20--%3E%20OK%5B%22%E5%8F%AF%E4%B8%8A%E6%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p><span class="marginnote">这张图回答的问题是：一张版「以周计」的日子花在哪。写入与光化鉴定这两段往往就是瓶颈——产能规划要按瓶颈机台排队算，而不是把各步平均一下。</span></p><p><span class="marginnote">术语翻译：AIMS 就是用与曝光机相同波长的光，在一台专用设备上对缺陷处做局部「预演成像」，裁决这个缺陷到底会不会印到晶圆上——它决定「修、报废还是放行」，也是排队的常见原因。</span></p><p>与晶圆成本衔接：掩模摊销 = 总成本 / 用这套版所跑的晶圆数。工程样品少片时掩模主导；量大时扫描机与胶主导。节点初期经常落在前者。</p><p><span class="marginnote">直觉类比：掩模摊销像请柬的制版费——只印 10 份，版费占大头；印 10 万份，纸和印刷机时间才是大头。工程样品只跑几百片晶圆时，一张版的钱摊到每片上就非常重，这就是「节点初期掩模主导」的意思。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ILT 与曲线把 MDP 与写入从「可预测的曼哈顿小时」推进「数据墙 + 多束机时」。检验对曲边更慢。合格率随缺陷规格变严而降，摊销上升。雾化再洗占用同一套清洗/检验，等于动态加成本。这些项进 TAPOUT 日历，从而进产品上市，而不只进 COGS 表格。</p>',6)),(t(),o(i,null,{default:e(()=>[s(E,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%B1%82%E6%95%B0%20%C3%97%20%E5%88%86%E8%A7%A3%E5%BC%A0%E6%95%B0%22%5D%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E5%A5%97%22%5D%0A%20%20DIFF%5B%22ILT%20%2F%20EUV%20%2F%20%E5%85%89%E5%8C%96%22%5D%20--%3E%20UNIT%5B%22%E5%8D%95%E5%BC%A0%E6%88%90%E6%9C%AC%E4%B8%8E%E5%A4%A9%E6%95%B0%22%5D%0A%20%20ITER%5B%22OPC%20%E8%BF%AD%E4%BB%A3%22%5D%20--%3E%20MASK%0A%20%20MASK%20--%3E%20AMORT%5B%22%E6%91%8A%E5%88%B0%E6%99%B6%E5%9C%86%22%5D%0A%20%20UNIT%20--%3E%20AMORT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造节点良率或掩模价目表。成本课不替代扫描机折旧课——那是后门路线图课。本课结束掩模制造主干。</p><p>后课默认：读者知道版的数据链、物理链与经济链；下一门课用 FDTD 等严格方法解释掩模开口里的电磁，为什么 3D 与 MPC 必须存在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模账是张数、单张难度、迭代与合格率，不是一句「EUV 更贵」。</li><li>周期常被写入与光化鉴定排队主导；改版按最慢张。</li><li>少片时摊销主导晶圆成本，量大时扫描机主导。</li><li>出处：掩模成本结构与 TAPOUT 周期的公开产业讨论；本课不引用无来源报价。</li></ul>',5))])}const f=A(d,[["render",h]]);export{C as __pageData,f as default};
